export type AppErrorCode =
  | 'AUTH_INVALID'
  | 'AUTH_PERMANENT'
  | 'TIMEOUT'
  | 'RATE_LIMIT'
  | 'PERMISSION'
  | 'CHANNEL_UNAVAILABLE'
  | 'CONVERSATION_STATE'
  | 'NETWORK'
  | 'CONFIG'
  | 'GATEWAY'
  | 'BILLING'
  | 'OVERLOADED'
  | 'MODEL_NOT_FOUND'
  | 'UNKNOWN';

/** The only operations a recovery instruction may ask the caller to perform. */
export type AppErrorActionKind =
  | 'retry'
  | 'reauthenticate'
  | 'reconfigure'
  | 'open-settings'
  | 'contact-support';

/** Bounded, non-executable targets for the two setting/configuration actions. */
export type AppErrorActionTarget = 'authentication' | 'provider' | 'model' | 'billing';

export type AppErrorNextAction = {
  kind: AppErrorActionKind;
  target?: AppErrorActionTarget;
};

export type AppErrorRecoveryScope = 'self' | 'user' | 'none';

export type AppErrorRecovery = {
  readonly retryable: boolean;
  readonly scope: AppErrorRecoveryScope;
  readonly action?: AppErrorNextAction;
};

/**
 * Every class the unified exit can render. Kept as a runtime list so copy,
 * retry and locale coverage can be audited exhaustively instead of by memory.
 */
export const APP_ERROR_CODES = [
  'AUTH_INVALID',
  'AUTH_PERMANENT',
  'TIMEOUT',
  'RATE_LIMIT',
  'PERMISSION',
  'CHANNEL_UNAVAILABLE',
  'CONVERSATION_STATE',
  'NETWORK',
  'CONFIG',
  'GATEWAY',
  'BILLING',
  'OVERLOADED',
  'MODEL_NOT_FOUND',
  'UNKNOWN',
] as const satisfies readonly AppErrorCode[];

/**
 * Stable recovery policy for every AppErrorCode.  `self` means the host may
 * safely repeat the same operation; `user` means an explicit user action is
 * required.  There are intentionally no shell, command, script, or arbitrary
 * parameter fields here.
 */
export const APP_ERROR_RECOVERY: { readonly [K in AppErrorCode]: AppErrorRecovery } = {
  AUTH_INVALID: {
    retryable: false,
    scope: 'user',
    action: { kind: 'reauthenticate', target: 'authentication' },
  },
  AUTH_PERMANENT: {
    retryable: false,
    scope: 'user',
    action: { kind: 'reauthenticate', target: 'authentication' },
  },
  TIMEOUT: {
    retryable: true,
    scope: 'self',
    action: { kind: 'retry' },
  },
  RATE_LIMIT: {
    retryable: true,
    scope: 'self',
    action: { kind: 'retry' },
  },
  PERMISSION: {
    retryable: false,
    scope: 'user',
    action: { kind: 'contact-support' },
  },
  CHANNEL_UNAVAILABLE: {
    retryable: true,
    scope: 'self',
    action: { kind: 'retry' },
  },
  CONVERSATION_STATE: {
    retryable: false,
    scope: 'user',
    action: { kind: 'reconfigure', target: 'provider' },
  },
  NETWORK: {
    retryable: true,
    scope: 'self',
    action: { kind: 'retry' },
  },
  CONFIG: {
    retryable: false,
    scope: 'user',
    action: { kind: 'reconfigure', target: 'provider' },
  },
  GATEWAY: {
    retryable: true,
    scope: 'self',
    action: { kind: 'retry' },
  },
  BILLING: {
    retryable: false,
    scope: 'user',
    action: { kind: 'open-settings', target: 'billing' },
  },
  OVERLOADED: {
    retryable: true,
    scope: 'self',
    action: { kind: 'retry' },
  },
  MODEL_NOT_FOUND: {
    retryable: false,
    scope: 'user',
    action: { kind: 'reconfigure', target: 'model' },
  },
  // Unknown failures are exposed to the user with their original error.
  // No recovery is invented because no safe retry or repair can be inferred.
  UNKNOWN: {
    retryable: false,
    scope: 'user',
  },
